mapper.select:
SELECT t.title_id, t.title_type, COALESCE(l.local_title, t.original_title) AS display_title, t.original_title, t.release_date, t.status FROM content_title t LEFT JOIN content_localization l ON l.title_id = t.title_id AND l.lang_code = #{lang} WHERE t.status <> 'DELETED'
AND t.title_type = #{titleType}
AND (t.original_title LIKE CONCAT('%', #{query}, '%') OR EXISTS (SELECT 1 FROM content_localization q WHERE q.title_id = t.title_id AND q.local_title LIKE CONCAT('%', #{query}, '%')))
ORDER BY t.release_date DESC, t.title_id DESC LIMIT #{limit}

mapper.sql:
WHERE t.status <> 'DELETED'

  AND t.title_type = #{titleType}


  AND t.status = #{status}


  AND t.is_animation = #{animation}


  AND EXISTS (SELECT 1 FROM content_title_genre fg WHERE fg.title_id = t.title_id AND fg.genre_code = #{genre})


  AND (t.original_title LIKE CONCAT('%', #{query}, '%')
       OR EXISTS (SELECT 1 FROM content_localization q
                   WHERE q.title_id = t.title_id AND q.local_title LIKE CONCAT('%', #{query}, '%')))
